# =============================================================================
# FUNÇÕES AUXILIARES
# =============================================================================

function Write-Step {
    # Mensagem de etapa com o padrão visual do script original.
    param([string]$Message)
    Write-Host "[+] $Message" -BackgroundColor Black -ForegroundColor Green
}

function Write-Info {
    param([string]$Message)
    Write-Host "    $Message" -BackgroundColor Black -ForegroundColor Gray
}

function Write-Warn-Script {
    param([string]$Message)
    Write-Host "[!] $Message" -BackgroundColor Black -ForegroundColor Yellow
}

function Expand-EmbeddedBinary {
    <#
    .SYNOPSIS
        Descompacta e extrai um binário embutido (gzip + base64) para disco.
    #>
    param(
        [string]$Base64,
        [string]$DestinationPath
    )
    # Remove whitespace e quebras de linha dos chunks de base64
    $clean = $Base64 -replace '\s', ''
    $gzipBytes = [Convert]::FromBase64String($clean)

    $src = New-Object System.IO.MemoryStream(, $gzipBytes)
    $gzs = New-Object System.IO.Compression.GzipStream($src, [System.IO.Compression.CompressionMode]::Decompress)
    $dst = New-Object System.IO.MemoryStream
    try {
        $gzs.CopyTo($dst)
    }
    finally {
        $gzs.Dispose()
        $src.Dispose()
    }
    [IO.File]::WriteAllBytes($DestinationPath, $dst.ToArray())
    $dst.Dispose()
}

function Wait-ProcessExit {
    <#
    .SYNOPSIS
        Aguarda um processo terminar com timeout (evita loop infinito).
    #>
    param(
        [string]$ProcessName,
        [int]$TimeoutSec = $script:ProcessTimeoutSec,
        [string]$ProgressText = $null
    )
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    while (Get-Process -Name $ProcessName -ErrorAction SilentlyContinue) {
        if ($sw.Elapsed.TotalSeconds -gt $TimeoutSec) {
            Write-Warn-Script "Timeout ($TimeoutSec s) aguardando o processo '$ProcessName' — prosseguindo mesmo assim."
            return $false
        }
        if ($ProgressText) { Write-Host $ProgressText -NoNewline -BackgroundColor Black -ForegroundColor Green }
        Start-Sleep -Seconds 1
    }
    $sw.Stop()
    return $true
}

function Get-FreeSpaceGB {
    # Espaço livre em GB no volume do caminho informado.
    param([string]$Path)
    try {
        $drive = (Get-Item -Path $Path -ErrorAction Stop).PSDrive.Name
        $free = (Get-PSDrive -Name $drive -ErrorAction Stop).Free
        return [math]::Round($free / 1GB, 2)
    }
    catch {
        return -1
    }
}

function Get-FileHashSafe {
    # Hash SHA256 de um arquivo, retornando string vazia em caso de falha.
    param([string]$Path)
    try {
        return (Get-FileHash -Path $Path -Algorithm SHA256 -ErrorAction Stop).Hash
    }
    catch {
        return ''
    }
}

# =============================================================================
# FUNÇÕES DE COLETA
# =============================================================================

function Invoke-RamDump {
    <#
    .SYNOPSIS
        Dump de memória RAM via WinPmem (embutido, open source).
        WinPmem é CLI puro — funciona headless (ao contrário do Magnet RAM
        Capture, que travava em execução não-interativa por ser GUI).
        O dump é gravado em <Out>\...\RAM\ (fora do zip final).
    #>
    param([string]$RamDir)

    Write-Step 'Dump de memória RAM (WinPmem)'
    New-Item -Path $RamDir -ItemType Directory -Force | Out-Null
    $dumpExe = Join-Path $RamDir 'N00-PMEM.exe'

    try {
        Expand-EmbeddedBinary -Base64 $script:N00PMEMB64 -DestinationPath $dumpExe
    }
    catch {
        Write-Warn-Script "Falha ao extrair o WinPmem: $($_.Exception.Message) — dump de RAM pulado."
        return
    }

    $dumpFile = Join-Path $RamDir ("{0}_{1}.raw" -f $env:COMPUTERNAME, (Get-Date -Format 'yyyyMMdd-HHmmss'))
    Write-Info "Capturando memória RAM ($([math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory/1GB,1)) GB — pode demorar)..."
    try {
        Start-Process -FilePath $dumpExe -ArgumentList "`"$dumpFile`"" -WorkingDirectory $RamDir -ErrorAction Stop
    }
    catch {
        Write-Warn-Script "Falha ao iniciar o WinPmem: $($_.Exception.Message) — dump de RAM pulado."
        return
    }
    $done = Wait-ProcessExit -ProcessName 'N00-PMEM' -TimeoutSec $script:HunterTimeoutSec -ProgressText '#'

    # Validação: o dump precisa existir e ter tamanho real (> 50 MB)
    if (Test-Path $dumpFile) {
        $sizeMB = [math]::Round((Get-Item $dumpFile).Length / 1MB, 1)
        if ($sizeMB -gt 50) {
            Write-Info "Dump concluído: $([IO.Path]::GetFileName($dumpFile)) ($sizeMB MB)"
            # Hash do dump para cadeia de custódia (arquivo grande — pode demorar)
            Write-Info 'Calculando SHA256 do dump de memória (pode demorar)...'
            $dumpHash = Get-FileHashSafe -Path $dumpFile
            "$dumpHash  $([IO.Path]::GetFileName($dumpFile))" | Out-File -FilePath (Join-Path $RamDir 'dump.sha256') -Encoding ASCII
            Write-Info "SHA256 do dump: $dumpHash"
        }
        else {
            Write-Warn-Script "Dump incompleto (apenas $sizeMB MB) — verifique espaço em disco."
            Remove-Item -Path $dumpFile -Force -ErrorAction SilentlyContinue
        }
    }
    else {
        Write-Warn-Script 'Nenhum arquivo de dump encontrado na pasta RAM (verifique espaço em disco).'
    }
    Write-Host ''
}

function Collect-SystemInfo {
    param([string]$Dir)
    Write-Step 'Informações do sistema (systeminfo)'
    try {
        systeminfo.exe /fo list 2>$null | Out-File -FilePath (Join-Path $Dir 'systeminfo.txt') -Encoding UTF8
        Write-Info 'systeminfo.txt coletado.'
    }
    catch {
        Write-Warn-Script "systeminfo falhou: $($_.Exception.Message)"
    }
}

function Collect-Processes {
    param([string]$Dir)
    Write-Step 'Processos em execução'
    try {
        Get-Process | Select-Object * | Out-File -FilePath (Join-Path $Dir 'os_processes.txt') -Encoding UTF8
        Write-Info 'os_processes.txt coletado.'
    }
    catch {
        Write-Warn-Script "Coleta de processos falhou: $($_.Exception.Message)"
    }
}

function Collect-NetworkTcp {
    param([string]$Dir)
    Write-Step 'Conexões TCP'
    $tcpFile = Join-Path $Dir 'net_tcp.txt'
    try {
        Get-NetTCPConnection | Select-Object OwningProcess, RemoteAddress, RemotePort, LocalAddress, LocalPort, State, CreationTime | Out-File -FilePath $tcpFile -Encoding UTF8
    }
    catch {
        # Fallback: netstat do próprio host (documentado como última alternativa)
        Write-Warn-Script "Get-NetTCPConnection indisponível — usando netstat como fallback: $($_.Exception.Message)"
        try {
            netstat.exe -ano | Out-File -FilePath $tcpFile -Encoding UTF8
        }
        catch {
            Write-Warn-Script 'netstat também falhou — sem dados de conexões TCP.'
        }
    }
    Write-Info 'net_tcp.txt coletado.'
}

function Collect-DnsCache {
    param([string]$Dir)
    Write-Step 'Cache DNS'
    try {
        Get-DnsClientCache | Select-Object Data, Entry | Out-File -FilePath (Join-Path $Dir 'dns_cache.txt') -Encoding UTF8
    }
    catch {
        Write-Warn-Script "Get-DnsClientCache falhou: $($_.Exception.Message)"
    }
}

function Collect-SmbShares {
    param([string]$Dir)
    Write-Step 'Compartilhamentos SMB'
    try {
        Get-SmbShare | Select-Object * | Out-File -FilePath (Join-Path $Dir 'smb_shares.txt') -Encoding UTF8
    }
    catch {
        Write-Warn-Script "Get-SmbShare falhou — usando net share: $($_.Exception.Message)"
        try {
            net.exe share | Out-File -FilePath (Join-Path $Dir 'smb_shares.txt') -Encoding UTF8
        }
        catch {
            Write-Warn-Script 'Sem dados de compartilhamentos.'
        }
    }
}

function Collect-LocalUsers {
    param([string]$Dir)
    Write-Step 'Usuários locais'
    $usersFile = Join-Path $Dir 'local_users.txt'
    try {
        if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
            Get-LocalUser | Select-Object * | Out-File -FilePath $usersFile -Encoding UTF8
        }
        else {
            throw 'Get-LocalUser indisponível'
        }
    }
    catch {
        Write-Warn-Script "Get-LocalUser falhou — usando net user: $($_.Exception.Message)"
        try {
            net.exe user | Out-File -FilePath $usersFile -Encoding UTF8
        }
        catch {
            Write-Warn-Script 'Sem dados de usuários locais.'
        }
    }
}

function Collect-Disks {
    param([string]$Dir)
    Write-Step 'Discos físicos e lógicos'
    try {
        Get-CimInstance Win32_DiskDrive | Select-Object * | Out-File -FilePath (Join-Path $Dir 'physical_disks.txt') -Encoding UTF8
        Get-CimInstance Win32_LogicalDisk | Select-Object * | Out-File -FilePath (Join-Path $Dir 'logical_disks.txt') -Encoding UTF8
        Write-Info 'physical_disks.txt e logical_disks.txt coletados.'
    }
    catch {
        Write-Warn-Script "Coleta de discos falhou: $($_.Exception.Message)"
    }
}

function Collect-Hotfixes {
    param([string]$Dir)
    Write-Step 'Hotfixes instalados'
    try {
        Get-Hotfix | Select-Object * | Out-File -FilePath (Join-Path $Dir 'hotfixes.txt') -Encoding UTF8
    }
    catch {
        Write-Warn-Script "Get-Hotfix falhou: $($_.Exception.Message)"
    }
}

function Collect-NetAdapters {
    param([string]$Dir)
    Write-Step 'Adaptadores de rede'
    try {
        Get-NetAdapter | Select-Object * | Out-File -FilePath (Join-Path $Dir 'net_adapters.txt') -Encoding UTF8
    }
    catch {
        Write-Warn-Script "Get-NetAdapter falhou — usando ipconfig /all: $($_.Exception.Message)"
        try {
            ipconfig.exe /all | Out-File -FilePath (Join-Path $Dir 'net_adapters.txt') -Encoding UTF8
        }
        catch {
            Write-Warn-Script 'Sem dados de adaptadores.'
        }
    }
}

function Collect-Services {
    param([string]$Dir)
    Write-Step 'Serviços do Windows (inclui caminho do executável)'
    try {
        # Win32_Service fornece PathName e StartName — mais valor forense que Get-Service
        Get-CimInstance Win32_Service | Select-Object Name, DisplayName, State, StartMode, StartName, PathName, Description, ProcessId | Out-File -FilePath (Join-Path $Dir 'services.txt') -Encoding UTF8
    }
    catch {
        Write-Warn-Script "Win32_Service falhou — usando Get-Service: $($_.Exception.Message)"
        try {
            Get-Service | Select-Object Status, StartType, Name, DisplayName, ServiceName | Out-File -FilePath (Join-Path $Dir 'services.txt') -Encoding UTF8
        }
        catch {
            Write-Warn-Script 'Sem dados de serviços.'
        }
    }
}

function Collect-Autoruns {
    param([string]$Dir)
    Write-Step 'Chaves de inicialização automática (autoruns)'
    $outputFile = Join-Path $Dir 'autoruns.txt'

    $autorunPaths = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunServices',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunServicesOnce',
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run',
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\RunServices',
        'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon',
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunServices',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer\Run'
    )

    $autoruns = @()
    foreach ($path in $autorunPaths) {
        if (-not (Test-Path $path)) { continue }
        try {
            $props = Get-ItemProperty -Path $path -ErrorAction Stop
            foreach ($prop in $props.PSObject.Properties) {
                # Ignora propriedades de infraestrutura do PSProvider
                if ($prop.Name -like 'PS*') { continue }
                $autoruns += [PSCustomObject]@{
                    Chave = $path
                    Nome  = $prop.Name
                    Valor = $prop.Value
                }
            }
        }
        catch {
            Write-Warn-Script "Falha ao ler a chave $path : $($_.Exception.Message)"
        }
    }
    $autoruns | Out-String -Width 400 | Out-File -FilePath $outputFile -Encoding UTF8
    Write-Info "autoruns.txt ($($autoruns.Count) entradas)."
}

function Collect-ScheduledTasks {
    param([string]$Dir)
    Write-Step 'Tarefas agendadas'
    try {
        Get-ScheduledTask | Select-Object State, TaskName, TaskPath, Description, Author | Out-File -FilePath (Join-Path $Dir 'scheduled_tasks.txt') -Encoding UTF8
        Get-ScheduledTask | ForEach-Object {
            $task = $_
            $task.Actions | ForEach-Object {
                [PSCustomObject]@{
                    TaskPath  = $task.TaskPath
                    TaskName  = $task.TaskName
                    Execute   = $_.Execute
                    Arguments = $_.Arguments
                }
            }
        } | Out-String -Width 500 | Out-File -FilePath (Join-Path $Dir 'scheduled_tasks_actions.txt') -Encoding UTF8
        Write-Info 'scheduled_tasks.txt e scheduled_tasks_actions.txt coletados.'
    }
    catch {
        Write-Warn-Script "Coleta de tarefas agendadas falhou: $($_.Exception.Message)"
    }
}

function Collect-ScheduledTaskHashes {
    <#
    .SYNOPSIS
        Calcula SHA256 dos executáveis apontados pelas tarefas agendadas (modo Full).
        Corrige o bug do original: itera objetos completos (TaskPath incluso),
        trata múltiplas ações por tarefa e variáveis de ambiente.
    #>
    param([string]$Dir)
    Write-Step 'Hashes dos executáveis das tarefas agendadas'
    $outFile = Join-Path $Dir 'scheduled_tasks_hashes.txt'

    try {
        $allTasks = Get-ScheduledTask -ErrorAction Stop
    }
    catch {
        Write-Warn-Script "Get-ScheduledTask falhou: $($_.Exception.Message)"
        return
    }

    foreach ($task in $allTasks) {
        foreach ($action in $task.Actions) {
            $exe = $action.Execute
            $line = "[$($task.TaskPath)$($task.TaskName)] Execute=$exe Arguments=$($action.Arguments)"

            if (-not $exe) {
                "$line | NO_EXECUTABLE (ação sem executável — ex: handler COM/WMI)" | Out-File -FilePath $outFile -Encoding UTF8 -Append
                continue
            }

            # Expande variáveis de ambiente e remove aspas
            $clean = $exe.Trim('"').Trim()
            if ($clean -match '%') {
                try {
                    $clean = [Environment]::ExpandEnvironmentVariables($clean)
                }
                catch {
                    # Variáveis de ambiente não resolvíveis — mantém o path original
                }
            }
            $clean = $clean -replace '"', ''

            if (-not $clean -or $clean -notmatch '\\') {
                "$line | PATH_INDISPONIVEL (não foi possível resolver o caminho)" | Out-File -FilePath $outFile -Encoding UTF8 -Append
                continue
            }

            if (-not (Test-Path $clean)) {
                "$line | ARQUIVO_AUSENTE (o executável não existe no disco)" | Out-File -FilePath $outFile -Encoding UTF8 -Append
                continue
            }

            $hash = Get-FileHashSafe -Path $clean
            if ($hash) {
                "$line | SHA256=$hash" | Out-File -FilePath $outFile -Encoding UTF8 -Append
            }
            else {
                "$line | HASH_FALHOU" | Out-File -FilePath $outFile -Encoding UTF8 -Append
            }
        }
    }
    Write-Info 'scheduled_tasks_hashes.txt gerado.'
}

function Collect-PsHistory {
    param([string]$UsersDir)
    Write-Step 'Histórico de execução do PowerShell (todos os usuários)'

    $users = Get-ChildItem -Path 'C:\Users' -Directory -ErrorAction SilentlyContinue
    foreach ($user in $users) {
        $userName = $user.Name
        if ($userName -in @('Public', 'Default', 'Default User', 'All Users')) { continue }

        $destUserDir = Join-Path $UsersDir $userName
        New-Item -Path $destUserDir -ItemType Directory -Force | Out-Null

        # Histórico PSReadLine
        $psHistory = "C:\Users\$userName\AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt"
        if (Test-Path $psHistory) {
            try {
                Copy-Item -Path $psHistory -Destination (Join-Path $destUserDir 'psreadline_history.txt') -Force -ErrorAction Stop
                Write-Info "Histórico PS de $userName coletado."
            }
            catch {
                Write-Warn-Script "Falha ao copiar histórico de $userName : $($_.Exception.Message)"
            }
        }

        # Pasta Startup
        $startup = "C:\Users\$userName\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup"
        if (Test-Path $startup) {
            try {
                Copy-Item -Path "$startup\*" -Destination (Join-Path $destUserDir 'startup') -Recurse -Force -ErrorAction Stop
                Write-Info "Pasta Startup de $userName coletada."
            }
            catch {
                Write-Warn-Script "Falha ao copiar Startup de $userName : $($_.Exception.Message)"
            }
        }
    }
}

function Collect-Evtx {
    param([string]$Dir)
    Write-Step 'Logs de eventos do Windows (.evtx)'
    try {
        Copy-Item -Path 'C:\Windows\System32\winevt\Logs\*' -Destination $Dir -Recurse -Force -ErrorAction Stop
        $count = (Get-ChildItem -Path $Dir -File -ErrorAction SilentlyContinue).Count
        Write-Info "$count arquivos .evtx copiados."
    }
    catch {
        # Alguns evtx podem estar travados — copia o que der
        Write-Warn-Script "Cópia parcial dos evtx: $($_.Exception.Message)"
        Copy-Item -Path 'C:\Windows\System32\winevt\Logs\*' -Destination $Dir -Recurse -Force -ErrorAction SilentlyContinue
        $count = (Get-ChildItem -Path $Dir -File -ErrorAction SilentlyContinue).Count
        Write-Info "$count arquivos .evtx copiados (parcial)."
    }
}

function Copy-From-VSS {
    <#
    .SYNOPSIS
        Copia arquivos travados (ex: registry hives em uso) via Volume Shadow Copy.
        Fluxo: snapshot do volume do sistema → expõe via symlink (mklink /d) →
        copia → remove symlink e snapshot (sempre, via finally).
        PS 5.1 não resolve \\?\GLOBALROOT\Device\... direto, por isso o symlink.
    #>
    param(
        [string[]]$SourcePaths,
        [string]$DestinationDir
    )
    $shadow = $null
    $link = Join-Path $env:TEMP ('N00FOR_VSS_' + [guid]::NewGuid().ToString('N').Substring(0, 8))
    try {
        # 1. Snapshot do volume do sistema
        $class = [WMIClass]'root\cimv2:Win32_ShadowCopy'
        $sc = $class.Create('C:\', 'ClientAccessible')
        if ($sc.ReturnValue -ne 0) {
            throw "Win32_ShadowCopy.Create falhou (return $($sc.ReturnValue))"
        }
        $shadow = Get-CimInstance Win32_ShadowCopy | Where-Object { $_.ID -eq $sc.ShadowID }
        if (-not $shadow) { throw 'Shadow copy não localizada após criação.' }

        # 2. Symlink de diretório para o volume da shadow
        $null = cmd /c mklink /d "$link" "$($shadow.DeviceObject)\"
        if (-not (Test-Path $link)) { throw 'Falha ao criar symlink para a shadow copy.' }

        # 3. Copia cada arquivo (assume volume C:\ — artefatos de sistema)
        foreach ($src in $SourcePaths) {
            $viaLink = Join-Path $link $src.Substring(3)
            if (Test-Path $viaLink) {
                Copy-Item -Path $viaLink -Destination $DestinationDir -Force -ErrorAction Stop
            }
            else {
                throw "Arquivo não encontrado na shadow copy: $src"
            }
        }
    }
    finally {
        # 4. Cleanup incondicional: nunca deixar shadow copy acumulando no cliente
        if (Test-Path $link) { $null = cmd /c rmdir $link }
        if ($shadow) { $shadow | Remove-CimInstance -Confirm:$false -ErrorAction SilentlyContinue }
    }
}

function Collect-Amcache {
    <#
    .SYNOPSIS
        Copia os arquivos Amcache (Program Execution) para análise OFFLINE.
        O parse (AmCacheParser/Eric Zimmerman) é feito no laboratório do analista.
        O Amcache.hve costuma estar travado pelo sistema — o fallback é VSS.
    #>
    param([string]$Dir)
    Write-Step 'Amcache (Program Execution) — cópia para análise offline'
    $amcacheDir = 'C:\Windows\appcompat\Programs'
    if (Test-Path $amcacheDir) {
        $files = @('Amcache.hve', 'Amcache.hve.LOG1', 'Amcache.hve.LOG2', 'RecentFileCache.bcf')
        $locked = @()
        foreach ($f in $files) {
            $src = Join-Path $amcacheDir $f
            if (Test-Path $src) {
                try {
                    Copy-Item -Path $src -Destination $Dir -Force -ErrorAction Stop
                    Write-Info "$f copiado."
                }
                catch {
                    # Arquivo em uso — tenta via VSS no final
                    $locked += $src
                }
            }
        }
        if ($locked.Count -gt 0) {
            Write-Info "Arquivos travados ($($locked.Count)) — copiando via Volume Shadow Copy..."
            try {
                Copy-From-VSS -SourcePaths $locked -DestinationDir $Dir
                Write-Info 'Arquivos do Amcache copiados via VSS.'
            }
            catch {
                Write-Warn-Script "Cópia via VSS falhou: $($_.Exception.Message)"
            }
        }
    }
    else {
        Write-Warn-Script 'Pasta do Amcache não encontrada (esperado em versões antigas do Windows).'
    }
}

function Collect-ListeningProcessHashes {
    <#
    .SYNOPSIS
        Modo Full: detalha processos com conexão TCP ativa (path, PID e hash).
    #>
    param([string]$Dir)
    Write-Step 'Processos com conexão de rede ativa (com hash)'

    try {
        $connections = Get-NetTCPConnection | Select-Object -ExpandProperty OwningProcess -Unique -ErrorAction Stop
    }
    catch {
        Write-Warn-Script 'Get-NetTCPConnection indisponível — etapa pulada.'
        return
    }

    Get-NetTCPConnection | Select-Object * | Out-File -FilePath (Join-Path $Dir 'listen_ports.txt') -Encoding UTF8

    $outFile = Join-Path $Dir 'listen_ports_process.txt'
    # NOTA: NUNCA usar $pid — é variável automática read-only (PID do processo atual)
    foreach ($procPid in $connections) {
        if (-not $procPid) { continue }
        "================================================================" | Out-File -FilePath $outFile -Encoding UTF8 -Append
        try {
            $proc = Get-Process -Id $procPid -ErrorAction Stop
            "PID=$procPid NAME=$($proc.ProcessName) PATH=$($proc.Path)" | Out-File -FilePath $outFile -Encoding UTF8 -Append

            if ($proc.Path) {
                $hash = Get-FileHashSafe -Path $proc.Path
                "SHA256=$hash" | Out-File -FilePath $outFile -Encoding UTF8 -Append
            }
            else {
                'SHA256=INDISPONIVEL (processo protegido do sistema)' | Out-File -FilePath $outFile -Encoding UTF8 -Append
            }
            Get-NetTCPConnection -OwningProcess $procPid -ErrorAction SilentlyContinue | Out-File -FilePath $outFile -Encoding UTF8 -Append
        }
        catch {
            "PID=$procPid ERRO=processo encerrou antes da coleta" | Out-File -FilePath $outFile -Encoding UTF8 -Append
        }
    }
    Write-Info 'listen_ports.txt e listen_ports_process.txt gerados.'
}

function Invoke-HollowsHunter {
    <#
    .SYNOPSIS
        Modo Full: varredura de processos em memória (hollowing, injeção, implants).
    #>
    param([string]$Dir)
    Write-Step 'Hollows Hunter — varredura de memória de processos'

    $hunterExe = Join-Path $Dir 'N00-Hunter.exe'
    try {
        Expand-EmbeddedBinary -Base64 $script:N00HUNTERB64 -DestinationPath $hunterExe
    }
    catch {
        Write-Warn-Script "Falha ao extrair o Hollows Hunter: $($_.Exception.Message) — etapa pulada."
        return
    }

    $scanLog = Join-Path $Dir 'N00-Hunter_scan.log'
    try {
        # /log faz o HH manter o próprio log no diretório; o stdout (relatório
        # da varredura) é capturado como evidência — em sistema limpo o HH não
        # gera dumps nem arquivos, então o log da varredura é o único artefato.
        Start-Process -FilePath $hunterExe -ArgumentList "/minidmp /log /dir `"$Dir`"" -RedirectStandardOutput $scanLog -ErrorAction Stop
        $done = Wait-ProcessExit -ProcessName 'N00-Hunter' -TimeoutSec $script:HunterTimeoutSec -ProgressText '.'
        if ($done) {
            Write-Info 'Hollows Hunter concluído (varredura registrada em N00-Hunter_scan.log).'
        }
        else {
            Write-Warn-Script 'Hollows Hunter excedeu o timeout — resultados podem estar parciais.'
        }
    }
    catch {
        Write-Warn-Script "Hollows Hunter falhou: $($_.Exception.Message)"
    }
    Write-Host ''
}

# =============================================================================
# MANIFEST E EMPACOTAMENTO
# =============================================================================

function New-Manifest {
    <#
    .SYNOPSIS
        Gera manifest.json com metadados da coleta e SHA256 de cada artefato.
    #>
    param(
        [string]$EvidenceDir,
        [string]$CollectionMode
    )

    Write-Step 'Gerando manifest.json (integridade dos artefatos)'

    $files = Get-ChildItem -Path $EvidenceDir -Recurse -File -ErrorAction SilentlyContinue
    $fileList = @()
    $i = 0
    foreach ($f in $files) {
        $i++
        Write-Host "`r    Calculando SHA256: $i/$($files.Count)" -NoNewline -BackgroundColor Black -ForegroundColor Gray
        $rel = $f.FullName.Substring($EvidenceDir.Length).TrimStart('\', '/')
        $fileList += [PSCustomObject]@{
            path   = $rel
            size   = $f.Length
            sha256 = (Get-FileHashSafe -Path $f.FullName)
        }
    }
    Write-Host ''

    $manifest = [ordered]@{
        schema_version = 1
        tool           = 'N00-FOR'
        version        = $script:Version
        collection_mode = $CollectionMode
        hostname       = $env:COMPUTERNAME
        collected_at   = (Get-Date).ToString('yyyy-MM-ddTHH:mm:ssK')
        ram_dump       = $(-not $NoRam -and $CollectionMode -eq 'Full')
        tools_used     = @{
            winpmem = $script:WinPmemVersion
            hollows_hunter     = $script:HollowsVersion
        }
        artifact_count = $files.Count
        artifacts      = $fileList
    }

    $manifestPath = Join-Path $EvidenceDir 'manifest.json'
    $manifest | ConvertTo-Json -Depth 5 | Out-File -FilePath $manifestPath -Encoding UTF8
    Write-Info "manifest.json gerado ($($files.Count) artefatos)."
    return $manifestPath
}

function New-CollectionZip {
    <#
    .SYNOPSIS
        Compacta a pasta de evidências em ZIP (System.IO.Compression.ZipFile)
        e gera o SHA256 do arquivo ZIP.
    #>
    param(
        [string]$EvidenceDir,
        [string]$ZipPath
    )

    Write-Step 'Compactando evidências em ZIP'
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    try {
        [System.IO.Compression.ZipFile]::CreateFromDirectory(
            $EvidenceDir,
            $ZipPath,
            [System.IO.Compression.CompressionLevel]::Optimal,
            $false
        )
    }
    catch {
        Write-Warn-Script "ZIP via ZipFile falhou ($($_.Exception.Message)) — tentando Compress-Archive."
        Compress-Archive -Path (Join-Path $EvidenceDir '*') -DestinationPath $ZipPath -Force -ErrorAction Stop
    }

    $zipHash = Get-FileHashSafe -Path $ZipPath
    "$zipHash  $([IO.Path]::GetFileName($ZipPath))" | Out-File -FilePath "$ZipPath.sha256" -Encoding ASCII

    $zipSize = [math]::Round((Get-Item $ZipPath).Length / 1MB, 2)
    Write-Info "ZIP criado: $ZipPath ($zipSize MB)"
    Write-Info "SHA256 do ZIP: $zipHash"
    return $zipHash
}

